CREATE TABLE IF NOT EXISTS public.wallet_transactions (id uuid DEFAULT gen_random_uuid() PRIMARY KEY, organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, wallet_id uuid NOT NULL REFERENCES public.wallet_accounts(id) ON DELETE CASCADE, transaction_type text NOT NULL CHECK (transaction_type IN ('CREDIT','DEBIT','REFUND','ADJUSTMENT')), amount numeric(14,2) NOT NULL CHECK (amount > 0), reference text, description text, created_by uuid REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now());